                    lab.onmousedown=function(ev){if(ev.detail!==2)return;ev.preventDefault();ev.stopPropagation();var ot=tags[ii];var rc=lab.getBoundingClientRect();var inp=document.createElement("input");inp.type="text";inp.value=ot;inp.style.cssText="position:fixed;z-index:99999;left:"+rc.left+"px;top:"+rc.top+"px;width:"+Math.max(80,rc.width)+"px;height:"+rc.height+"px;padding:1px 4px;border:1px solid #4fc3f7;border-radius:3px;background:#16213e;color:#e0e0e0;font-size:11px;outline:none;";document.body.appendChild(inp);inp.focus();inp.select();inp.onblur=function(){var v=inp.value.trim();inp.remove();if(v&&v!==ot){var t2=getTags();t2[ii]=v;setTags(t2);}};inp.onkeydown=function(ev2){if(ev2.key==="Enter"){ev2.preventDefault();inp.blur();}if(ev2.key==="Escape"){ev2.preventDefault();inp.remove();}};};
