                            cnt++;
                            var card = document.createElement('div');
                            card.style.cssText = 'display:flex;flex-direction:column;align-items:center;width:calc(33.3% - 6px);min-width:130px;padding:4px;border-radius:6px;background:#16213e;cursor:pointer;box-sizing:border-box;position:relative;';
                            // ── ⭐ 按钮 ──
